'use client';
import { useEffect,useMemo,useState } from 'react';
import { ArrowRight, Play, Pause, SkipForward, RotateCcw, Maximize2, Minimize2, PanelLeftClose, PanelRightClose, Download, SlidersHorizontal, LockKeyhole, GitBranch, ChevronDown, Check, Radio, RefreshCw, X } from 'lucide-react';
import { DEFAULT_PROFILE, NODE_IDS, NODE_LABELS, QUESTIONS, ProfileSchema, type CompanyProfile, type NodeId, type RunSnapshot, type WorkflowEvent, type FieldId, type ResumeInput } from '../shared/contracts';
import { consumeSSE, mergeEvents, projectEvents, statusLabels, currentAnswers } from '../client/events';
import WorkflowGraph from './WorkflowGraph';
const statusText:Record<string,string>={ready:'Pronto al replay',running:'Workflow in corso',interrupted:'In attesa di una persona',completed:'Qualificazione completata',failed:'Esecuzione interrotta'};
const eventLabels:Record<WorkflowEvent['type'],string>={node_started:'Avvio nodo',node_completed:'Nodo completato',state_updated:'Stato aggiornato',route_selected:'Percorso selezionato',run_interrupted:'Intervento richiesto',run_completed:'Scheda pronta',run_failed:'Errore tecnico'};
const fieldLabels:Record<FieldId,string>={budget:'Budget',users:'Utenti',deadline:'Scadenza',integrations:'Integrazioni'};
function Json({value}:{value:unknown}){return <pre>{value===undefined?'Nessun dato a questo punto del percorso.':JSON.stringify(value,null,2)}</pre>}
function download(value:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='briefflow-scheda.json';a.click();URL.revokeObjectURL(url);}
export default function BriefFlow(){
 const [demos,setDemos]=useState<RunSnapshot[]>([]),[demoStatus,setDemoStatus]=useState('loading'),[snapshot,setSnapshot]=useState<RunSnapshot>(),[events,setEvents]=useState<WorkflowEvent[]>([]),[cursor,setCursor]=useState(0),[playing,setPlaying]=useState(false),[speed,setSpeed]=useState(1),[mode,setMode]=useState<'replay'|'live'>('replay'),[selectedOverride,setSelected]=useState<NodeId>(),[tab,setTab]=useState('graph'),[detailTab,setDetailTab]=useState('output'),[presentation,setPresentation]=useState(false),[left,setLeft]=useState(true),[right,setRight]=useState(true),[profileOpen,setProfileOpen]=useState(false),[profile,setProfile]=useState<CompanyProfile>(DEFAULT_PROFILE),[brief,setBrief]=useState(''),[token,setToken]=useState(''),[authenticated,setAuthenticated]=useState(false),[liveAvailable,setLiveAvailable]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[answers,setAnswers]=useState<Partial<Record<FieldId,string>>>({});
 const [runId,setRunId]=useState<string>();const [inspectNode,setInspectNode]=useState(false);
 const visible=useMemo(()=>mode==='replay'?events.slice(0,cursor):events,[events,cursor,mode]);const view=useMemo(()=>projectEvents(visible),[visible]);const selected=selectedOverride??[...visible].reverse().find(event=>event.node)?.node??'validate';const detail=view.nodes[selected];
 const loadDemo=(demo:RunSnapshot)=>{setRunId(undefined);const url=new URL(window.location.href);url.searchParams.delete('run');window.history.replaceState({},'',url);setSnapshot(demo);setEvents(mergeEvents([],demo.events));setCursor(0);setPlaying(false);setBrief(demo.state.brief);setSelected(undefined);setInspectNode(false);setError('');setAnswers({});};
 useEffect(()=>{fetch('/api/demos').then(r=>{if(!r.ok)throw Error();return r.json()}).then(body=>{const items=body.demos as RunSnapshot[];setDemos(items);setDemoStatus(items.length?'ready':'empty');if(items[0]&&!new URLSearchParams(window.location.search).has('run'))loadDemo(items[0]);}).catch(()=>setDemoStatus('error'));fetch('/api/config').then(r=>r.json()).then(body=>{setAuthenticated(body.authenticated);setLiveAvailable(body.liveAvailable)}).catch(()=>{});},[]);
 useEffect(()=>{if(!playing||mode!=='replay')return;if(cursor>=events.length)return;const timer=setTimeout(()=>{setSelected(undefined);setCursor(c=>Math.min(c+1,events.length));if(cursor+1>=events.length)setPlaying(false);},1100/speed);return ()=>clearTimeout(timer);},[playing,cursor,events.length,speed,mode]);
 useEffect(()=>{const params=new URLSearchParams(window.location.search);const id=params.get('run');if(id){fetch(`/api/runs/${encodeURIComponent(id)}`).then(async r=>{if(!r.ok)throw Error('Accedi come proprietario per recuperare questa esecuzione.');return r.json()}).then((data:RunSnapshot)=>{setRunId(id);setMode('live');setSnapshot(data);setEvents(mergeEvents([],data.events));setBrief(data.state.brief)}).catch(e=>{setRunId(id);setMode('live');setError(e.message)});}},[]);
 async function authenticate(){setBusy(true);setError('');try{const response=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});if(!response.ok)throw Error('Token non valido. Riprova.');setToken('');setAuthenticated(true);}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function recover(){const id=runId;if(!id)return;setBusy(true);try{const response=await fetch(`/api/runs/${encodeURIComponent(id)}`);if(!response.ok)throw Error('Stato non recuperato. Verifica accesso e connessione.');const data=await response.json() as RunSnapshot;setSnapshot(data);setEvents(current=>mergeEvents(current,data.events));setError('');}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 async function stream(resume?:Partial<ResumeInput>){if(busy)return;setBusy(true);setError('');setPlaying(false);if(!resume){setEvents([]);setRunId(undefined);}try{const response=await fetch(resume?`/api/runs/${encodeURIComponent(runId||'')}/resume`:'/api/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(resume?{requestId:crypto.randomUUID(),...resume}:{brief,profile,requestId:crypto.randomUUID()})});await consumeSSE(response,event=>{setRunId(event.run_id);const url=new URL(window.location.href);url.searchParams.set('run',event.run_id);window.history.replaceState({},'',url);setEvents(current=>mergeEvents(current,[event]));});}catch(e){setError(`${(e as Error).message} Puoi recuperare lo stato salvato.`);}finally{setBusy(false)}}
 const card=inspectNode?undefined:view.card;const questions=(view.interrupt?.payload.questions||[]) as FieldId[];
 const requestPanel=<aside className="request-panel panel"><div className="panel-heading"><h2>La richiesta</h2><span className="mono">INPUT</span></div><label className="field">Scenario dimostrativo<select value={snapshot?.demo?snapshot.id:''} onChange={e=>{const demo=demos.find(d=>d.id===e.target.value);if(demo){setMode('replay');loadDemo(demo)}}} disabled={busy||!demos.length}><option value="">{demoStatus==='loading'?'Caricamento scenari…':'Scegli uno scenario'}</option>{demos.map((demo,index)=><option key={demo.id} value={demo.id}>{index+1}. {demo.label||demo.id}</option>)}</select></label>{demoStatus==='error'&&<p className="error-text">Scenari non disponibili. Ricarica la pagina per riprovare.</p>}{demoStatus==='empty'&&<p>Nessuno scenario pubblicato.</p>}<label className="field brief-label">Brief di progetto<textarea value={brief} readOnly={mode==='replay'} onChange={e=>setBrief(e.target.value)} maxLength={12000} placeholder="Incolla una richiesta di progetto…"/></label><div className="brief-meta"><span>{brief.length} caratteri</span><span>{mode==='replay'?'Dati sintetici':'Massimo 12.000'}</span></div><div className="profile-summary"><div><SlidersHorizontal size={15}/><strong>Profilo aziendale</strong></div><p>{profile.name}</p><button className="text-button" onClick={()=>setProfileOpen(!profileOpen)}>{profileOpen?'Chiudi configurazione':'Configura criteri'}<ChevronDown size={14}/></button></div>{profileOpen&&<ProfileEditor profile={profile} onChange={setProfile} onError={setError}/>}{mode==='live'&&<div className="live-access"><h3><LockKeyhole size={15}/>Accesso proprietario</h3>{!authenticated?<><label className="field">Token di accesso<input type="password" autoComplete="off" value={token} onChange={e=>setToken(e.target.value)}/></label><button onClick={authenticate} disabled={busy||!token}>Accedi</button></>:<p><Check size={14}/>Sessione autenticata</p>}<button className="primary" onClick={()=>stream()} disabled={!authenticated||!liveAvailable||busy||brief.trim().length<15}>{busy?'Esecuzione in corso…':'Qualifica richiesta'}<ArrowRight size={15}/></button>{!liveAvailable&&<p className="small">Live non configurato sul server. I replay pubblici restano disponibili.</p>}</div>}<div className="method-note"><GitBranch size={16}/><p><strong>Decisioni, non generazione.</strong> Jev valuta criteri strutturati. LangGraph gestisce il percorso e le attese umane.</p></div></aside>;
 const detailsPanel=<aside className="details-panel panel"><div className="panel-heading"><h2>{card?'Scheda finale':'Dettaglio nodo'}</h2><span className="mono">{card?'OUTPUT':'INSPECT'}</span></div>{view.card&&<div className="detail-tabs result-tabs"><button aria-pressed={!inspectNode} onClick={()=>setInspectNode(false)}>Scheda finale</button><button aria-pressed={inspectNode} onClick={()=>setInspectNode(true)}>Ispeziona nodi</button></div>}{card?<><div className="final-heading"><Check size={22}/><h3>Richiesta qualificata</h3><p>{card.summary}</p></div><dl className="card-fields"><dt>Categoria</dt><dd>{card.category}</dd><dt>Compatibilità</dt><dd>{({in_scope:'In linea',out_of_scope:'Fuori ambito',uncertain:'Da verificare'})[card.compatibility]}</dd><dt>Prossima azione</dt><dd>{({request_clarifications:'Richiedere chiarimenti',manual_review:'Revisione manuale',ready_for_review:'Pronta per revisione',closed_out_of_scope:'Chiusa: fuori ambito'})[card.nextAction]}</dd><dt>Informazioni mancanti</dt><dd>{card.missing.map(id=>fieldLabels[id]).join(', ')||'Nessuna'}</dd><dt>Vincoli</dt><dd>{card.constraints.join(', ')||'Nessuno rilevato'}</dd><dt>Da approfondire</dt><dd>{card.ambiguities.join(', ')||'Nessun punto'}</dd><dt>Risposte raccolte</dt><dd>{Object.entries(card.answers).map(([id,value])=><div key={id}>{fieldLabels[id as FieldId]}: {value}</div>)}</dd></dl><button className="export" onClick={()=>download(card)}><Download size={15}/>Esporta scheda JSON</button><p className="small">Profilo v{card.profileVersion} · {card.model} · {card.clarificationRound} giri</p></>:<><div className="node-detail-title"><span>{NODE_IDS.indexOf(selected)+1} / {NODE_IDS.length}</span><h3>{NODE_LABELS[selected]}</h3><p className={`status-inline ${detail.status}`}>{statusLabels[detail.status]}</p></div><div className="detail-metrics"><div><span>Durata ultima visita</span><strong>{detail.duration?`${detail.duration} ms`:'—'}</strong></div><div><span>Visite</span><strong>{detail.visits}</strong></div></div><div className="detail-tabs" role="tablist" aria-label="Dati nodo">{['input','output','diff'].map(t=><button key={t} role="tab" aria-selected={detailTab===t} onClick={()=>setDetailTab(t)}>{t==='diff'?'Differenze':t==='input'?'Input':'Output'}</button>)}</div><Json value={detailTab==='input'?detail.input:detailTab==='output'?detail.output:detail.patch}/></>}{view.interrupt&&<div className="human-action"><h3>Il workflow attende una persona</h3>{mode==='replay'?<p>Interruzione salvata. Avanza nel replay per osservare la risposta dimostrativa e la ripresa.</p>:view.interrupt.payload.kind==='manual_review'?<><p>Conferma il percorso della richiesta.</p><button disabled={busy} onClick={()=>stream({decision:'continue'})}>Prosegui la valutazione</button><button disabled={busy} onClick={()=>stream({decision:'close'})}>Chiudi come fuori ambito</button></>:<><form onSubmit={e=>{e.preventDefault();stream({answers:currentAnswers(questions,answers)})}}>{questions.map(id=><label className="field" key={id}>{QUESTIONS[id]}<input required maxLength={500} value={answers[id]||''} onChange={e=>setAnswers({...answers,[id]:e.target.value})}/></label>)}<button className="primary" disabled={busy}>Invia e riprendi<ArrowRight size={14}/></button></form></>}</div>}{mode==='live'&&snapshot?.status==='running'&&view.status==='running'&&!busy&&<div className="human-action"><h3>Esecuzione recuperata</h3><p>Riprendi dal checkpoint salvato. Se il server sta ancora lavorando, la protezione impedisce un secondo avvio.</p><button onClick={()=>stream({retry:true})}>Riprendi dal checkpoint</button></div>}{view.failure&&<div className="human-action error-text"><h3>Errore tecnico</h3><p>{String(view.failure.payload.message||'Esecuzione non completata.')}</p>{mode==='live'&&view.failure.payload.retryable===true&&<button disabled={busy} onClick={()=>stream({retry:true})}>Riprova dal checkpoint</button>}</div>}</aside>;
 return <div className={`app ${presentation?'presentation':''}`}><header className="topbar"><a className="brand" href="/" aria-label="BriefFlow home"><GitBranch size={25}/><span>Brief<span>Flow</span></span></a><div className="workspace-name">Workspace dimostrativo<span>/</span> Qualificazione progetti</div><div className="header-actions"><span className="engine">LangGraph + Jev</span><button onClick={()=>setPresentation(!presentation)} title="Modalità presentazione">{presentation?<Minimize2 size={15}/>:<Maximize2 size={15}/>}<span>{presentation?'Esci':'Presenta'}</span></button></div></header><main className="sheet"><div className="titlebar"><div><h1>Il percorso di una richiesta</h1><p>Dal brief alla prossima azione. Ogni passaggio, osservabile.</p></div><div className="mode-switch" aria-label="Modalità"><button className={mode==='replay'?'active':''} onClick={()=>{setMode('replay');setPlaying(false);if(demos[0])loadDemo(demos[0])}}>Replay demo</button><button disabled={busy} className={mode==='live'?'active':''} onClick={()=>{setMode('live');setPlaying(false);setEvents([]);setSnapshot(undefined);setRunId(undefined);setError('')}}><Radio size={13}/>Live riservato</button></div></div><div className="disclosure"><span className={`signal ${view.status}`}/><strong aria-live="polite">{statusText[view.status]}</strong><span>{mode==='replay'?'Replay pubblico · dati sintetici · decisioni simulate, nessuna chiamata Jev':'Esecuzione live · decisioni Jev reali · accesso protetto'}</span><div className="panel-toggles"><button aria-label={left?'Nascondi richiesta':'Mostra richiesta'} onClick={()=>setLeft(!left)}><PanelLeftClose size={15}/></button><button aria-label={right?'Nascondi dettagli':'Mostra dettagli'} onClick={()=>setRight(!right)}><PanelRightClose size={15}/></button></div></div>{error&&<div className="error-banner" role="alert"><span>{error}</span>{mode==='live'&&runId&&<button onClick={recover} disabled={busy}><RefreshCw size={14}/>Recupera stato</button>}<button aria-label="Chiudi messaggio" onClick={()=>setError('')}><X size={15}/></button></div>}<nav className="mobile-tabs" aria-label="Viste workspace">{[['request','Richiesta'],['graph','Grafo'],['details','Dettagli']].map(([id,label])=><button key={id} aria-current={tab===id?'page':undefined} onClick={()=>setTab(id)}>{label}</button>)}</nav><div className={`workbench ${left?'':'hide-left'} ${right?'':'hide-right'}`}><div className={`left-slot ${tab==='request'?'mobile-active':''}`}>{requestPanel}</div><section className={`graph-panel ${tab==='graph'?'mobile-active':''}`} aria-label="Grafo del workflow"><div className="graph-heading"><div><GitBranch size={16}/><h2>Workflow di qualificazione</h2></div><span>{visible.length} / {events.length} eventi</span></div><div className="graph-canvas"><WorkflowGraph events={visible} selected={selected} onSelect={id=>{setInspectNode(true);setSelected(id);setTab('details');setDetailTab('output')}}/></div><div className="graph-legend"><span><i className="legend-line"/>Percorso attraversato</span><span><i/>In attesa</span><span><i className="human"/>Intervento umano</span></div></section><div className={`right-slot ${tab==='details'?'mobile-active':''}`}>{detailsPanel}</div></div><section className="timeline" aria-label="Cronologia e replay"><div className="playback"><div className="playback-title"><strong>{mode==='replay'?'Replay degli eventi':'Cronologia live'}</strong><span>{mode==='replay'?'Riproduzione locale, nessuna API':'Eventi persistiti dal server'}</span></div><div className="playback-controls"><button aria-label="Ricomincia replay" disabled={mode!=='replay'||!events.length} onClick={()=>{setCursor(0);setPlaying(false)}}><RotateCcw size={16}/></button><button className="play-button" aria-label={playing?'Pausa replay':'Riproduci replay'} disabled={mode!=='replay'||!events.length} onClick={()=>{if(cursor>=events.length)setCursor(0);setPlaying(!playing)}}>{playing?<Pause size={16}/>:<Play size={16}/>}</button><button aria-label="Evento successivo" disabled={mode!=='replay'||cursor>=events.length} onClick={()=>{setPlaying(false);setCursor(c=>Math.min(c+1,events.length))}}><SkipForward size={16}/></button><select aria-label="Velocità replay" value={speed} onChange={e=>setSpeed(Number(e.target.value))} disabled={mode!=='replay'}>{[.5,1,1.5,2,4].map(n=><option key={n} value={n}>{n}×</option>)}</select><span className="mono counter">{String(mode==='replay'?cursor:events.length).padStart(2,'0')} / {events.length}</span></div><label className="scrubber"><span className="sr-only">Posizione replay</span><input type="range" min={0} max={events.length||1} value={mode==='replay'?cursor:events.length} disabled={mode!=='replay'||!events.length} onChange={e=>{setPlaying(false);setCursor(Number(e.target.value))}}/></label></div><div className="event-track">{visible.length===0?<p className="timeline-empty">Premi Riproduci per seguire le decisioni, un evento alla volta.</p>:visible.slice(-12).reverse().map(event=><button className="event-item" key={event.id} onClick={()=>{if(event.node){setInspectNode(true);setSelected(event.node);setTab('details')} }}><span className="mono">{String(event.seq).padStart(2,'0')}</span><div><strong>{event.node?NODE_LABELS[event.node]:eventLabels[event.type]}</strong><span>{event.type==='route_selected'?`${event.payload.label||'Percorso'} → ${NODE_LABELS[event.payload.target as NodeId]||event.payload.target}`:eventLabels[event.type]}</span></div><time>{new Date(event.timestamp).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}</time></button>)}</div></section><footer className="footer"><span>BriefFlow<span className="footer-dot">·</span>Orchestrazione visibile, decisioni verificabili.</span><span>LangGraph → Jev → Persona</span></footer></main></div>;
}
function ProfileEditor({profile,onChange,onError}:{profile:CompanyProfile;onChange:(p:CompanyProfile)=>void;onError:(e:string)=>void}){const [draft,setDraft]=useState(profile);return <form className="profile-editor" onSubmit={e=>{e.preventDefault();const result=ProfileSchema.safeParse(draft);if(!result.success){onError('Verifica il profilo: almeno due categorie e un campo obbligatorio.');return;}onChange({...result.data,version:profile.version+1});onError('')}}><label className="field">Nome azienda<input required maxLength={120} value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label className="field">Servizi (uno per riga)<textarea required value={draft.services.join('\n')} onChange={e=>setDraft({...draft,services:e.target.value.split('\n')})}/></label><label className="field">Categorie (una per riga)<textarea required value={draft.categories.join('\n')} onChange={e=>setDraft({...draft,categories:e.target.value.split('\n')})}/></label><label className="field">Criteri di compatibilità<textarea required maxLength={2000} value={draft.criteria} onChange={e=>setDraft({...draft,criteria:e.target.value})}/></label><fieldset><legend>Informazioni obbligatorie</legend>{(Object.keys(QUESTIONS) as FieldId[]).map(id=><label className="checkbox" key={id}><input type="checkbox" checked={draft.requiredFields.includes(id)} onChange={e=>setDraft({...draft,requiredFields:e.target.checked?[...draft.requiredFields,id]:draft.requiredFields.filter(f=>f!==id)})}/>{fieldLabels[id]}</label>)}</fieldset><label className="field">Soglia compatibilità<input type="number" min="0" max="1" step="0.05" value={draft.confidenceThreshold} onChange={e=>setDraft({...draft,confidenceThreshold:Number(e.target.value)})}/></label><label className="field">Soglia presenza<input type="number" min="0" max="1" step="0.05" value={draft.presenceThreshold} onChange={e=>setDraft({...draft,presenceThreshold:Number(e.target.value)})}/></label><button type="submit">Applica profilo <Check size={14}/></button><p className="small">Versione attiva: {profile.version}. Applicato alla prossima esecuzione live.</p></form>}
